        type: "list",
        items: [
            { id: "color_deficiency", title: "1. Thiếu màu", icon: "<div style='font-size:32px; display:flex; align-items:center; justify-content:center; width:100%; height:100%; color:#bdc3c7;'>⚪</div>", color: "transparent" },
            { id: "color_excess", title: "2. Thừa màu", icon: "<div style='font-size:32px; display:flex; align-items:center; justify-content:center; width:100%; height:100%; color:#e74c3c;'>🔴</div>", color: "transparent" }
        ]
